insert into kairo.questions (id, subject, topic, subtopic, learning_objective, concepts_tested, difficulty_rating, cognitive_level, estimated_solving_time_sec, reading_load, calculation_load, distractors, source, year, exam_body, stem, options, correct_option, explanation, lifecycle_state, distractor_rationale) values
($q$chemistry_0355$q$, $q$Chemistry$q$, $q$Atomic Structure & Bonding$q$, $q$Ionic vs Covalent Character — Fajan's Rules$q$, $q$Answer a real JAMB 2002 question on Ionic vs Covalent Character — Fajan's Rules.$q$, $q$[{"conceptId": "epcv95", "weight": 1}]$q$::jsonb, 3, $q$application$q$, 69, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "Li+ is a small cation but only has a +1 charge \u2014 its polarising power is much weaker than a +3 cation, so LiCl actually retains more ionic character than AlCl3.", "misconceptionId": "overgeneralized_rule"}, {"option": "B", "explanation": "Mg2+ has a +2 charge, giving intermediate polarising power \u2014 still weaker than Al3+'s +3 charge, so MgCl2 has more ionic character than AlCl3, not less.", "misconceptionId": "overgeneralized_rule"}, {"option": "C", "explanation": "Ca2+ is also +2 charged and larger than Mg2+, giving it even weaker polarising power \u2014 CaCl2 is actually one of the more ionic chlorides in this set, not the least.", "misconceptionId": "overgeneralized_rule"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$Which of the following chlorides would exhibit the least ionic character?$q$, $q$[{"label": "A", "text": "LiCl", "isCorrect": false}, {"label": "B", "text": "MgCl2", "isCorrect": false}, {"label": "C", "text": "CaCl2", "isCorrect": false}, {"label": "D", "text": "AlCl3", "isCorrect": true}]$q$::jsonb, $q$D$q$, $q$By Fajan's rules, ionic character decreases as the cation's charge increases and its size decreases, because a small, highly-charged cation polarises the electron cloud of the neighbouring chloride ion strongly, pulling shared electron density toward itself and giving the bond covalent character. Al3+ has the highest charge (+3) and a small ionic radius among these options, giving AlCl3 the strongest polarising power and therefore the least ionic (most covalent) character.$q$, $q$live$q$, $q$A: Li+ is a small cation but only has a +1 charge — its polarising power is much weaker than a +3 cation, so LiCl actually retains more ionic character than AlCl3. B: Mg2+ has a +2 charge, giving intermediate polarising power — still weaker than Al3+'s +3 charge, so MgCl2 has more ionic character than AlCl3, not less. C: Ca2+ is also +2 charged and larger than Mg2+, giving it even weaker polarising power — CaCl2 is actually one of the more ionic chlorides in this set, not the least.$q$),
($q$chemistry_0356$q$, $q$Chemistry$q$, $q$Kinetic Theory & Gas Laws$q$, $q$Gas Laws$q$, $q$Answer a real JAMB 2002 question on Gas Laws.$q$, $q$[{"conceptId": "84csd7", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 57, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "552.0 cm3 looks like it came from multiplying by a factor of 6 (perhaps from a units mix-up), rather than the actual small ratio of 291/276 K \u2014 nowhere near the correct proportional increase.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "87.3 cm3 is actually a decrease, but temperature is rising here so volume should increase, not fall, at constant pressure \u2014 this suggests the temperature ratio was inverted (T1/T2 instead of T2/T1).", "misconceptionId": "sign_error"}, {"option": "D", "explanation": "15.3 cm3 is a drastic and implausible drop \u2014 this doesn't correspond to any correct or even inverted form of Charles' law calculation with these numbers.", "misconceptionId": "arithmetic_slip"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$A fixed mass of gas has a volume of 92 cm3 at 3°C. What will be its volume at 18°C if the pressure remains constant?$q$, $q$[{"label": "A", "text": "552.0 cm3", "isCorrect": false}, {"label": "B", "text": "97.0 cm3", "isCorrect": true}, {"label": "C", "text": "87.3 cm3", "isCorrect": false}, {"label": "D", "text": "15.3 cm3", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Charles' law requires absolute temperature: T1 = 3 + 273 = 276 K, T2 = 18 + 273 = 291 K. V2 = V1 × (T2/T1) = 92 × (291/276) ≈ 97.0 cm3.$q$, $q$live$q$, $q$A: 552.0 cm3 looks like it came from multiplying by a factor of 6 (perhaps from a units mix-up), rather than the actual small ratio of 291/276 K — nowhere near the correct proportional increase. C: 87.3 cm3 is actually a decrease, but temperature is rising here so volume should increase, not fall, at constant pressure — this suggests the temperature ratio was inverted (T1/T2 instead of T2/T1). D: 15.3 cm3 is a drastic and implausible drop — this doesn't correspond to any correct or even inverted form of Charles' law calculation with these numbers.$q$),
($q$chemistry_0357$q$, $q$Chemistry$q$, $q$Environmental Pollution$q$, $q$The Carbon Cycle$q$, $q$Answer a real JAMB 2002 question on The Carbon Cycle.$q$, $q$[{"conceptId": "h2ua90", "weight": 1}]$q$::jsonb, 2, $q$recall$q$, 37, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Photosynthesis is a CO2-removing process, not a CO2-returning one \u2014 including it here reverses its actual role in the carbon cycle.", "misconceptionId": "overgeneralized_rule"}, {"option": "C", "explanation": "This also incorrectly includes photosynthesis as a source of atmospheric CO2, when it is in fact the main process that pulls CO2 out of the atmosphere.", "misconceptionId": "overgeneralized_rule"}, {"option": "D", "explanation": "Ozone depletion is a stratospheric ozone-layer issue, unrelated to the carbon cycle's movement of CO2 \u2014 mixing environmental topics together here is the error.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$The processes which return carbon(IV) oxide to the atmosphere include$q$, $q$[{"label": "A", "text": "Photosynthesis, respiration and transpiration", "isCorrect": false}, {"label": "B", "text": "Respiration, decay and combustion", "isCorrect": true}, {"label": "C", "text": "Photosynthesis, decay and respiration", "isCorrect": false}, {"label": "D", "text": "Ozone depletion, combustion and decay", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Respiration, decay (decomposition of organic matter), and combustion (burning fuels) all release CO2 into the atmosphere. Photosynthesis does the opposite — it removes CO2 from the atmosphere to build plant biomass — so any option including photosynthesis as a 'return' process is incorrect, and ozone depletion is unrelated to the carbon cycle.$q$, $q$live$q$, $q$A: Photosynthesis is a CO2-removing process, not a CO2-returning one — including it here reverses its actual role in the carbon cycle. C: This also incorrectly includes photosynthesis as a source of atmospheric CO2, when it is in fact the main process that pulls CO2 out of the atmosphere. D: Ozone depletion is a stratospheric ozone-layer issue, unrelated to the carbon cycle's movement of CO2 — mixing environmental topics together here is the error.$q$),
($q$chemistry_0358$q$, $q$Chemistry$q$, $q$Atomic Structure & Bonding$q$, $q$History of Atomic Theory$q$, $q$Answer a real JAMB 2002 question on History of Atomic Theory.$q$, $q$[{"conceptId": "nucy3t", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 57, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "This postulate has since been disproved \u2014 atoms are made of subatomic particles (protons, neutrons, electrons) and are therefore divisible, contrary to Dalton's original claim.", "misconceptionId": "overgeneralized_rule"}, {"option": "B", "explanation": "This describes combination in fixed ratios, which is still broadly true, but it is not the postulate most directly and universally cited as 'still holding' in the way atom conservation is \u2014 this is a plausible-sounding but not the intended best answer.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "This postulate has been disproved by the discovery of isotopes \u2014 atoms of the same element can have different masses (different numbers of neutrons), so they are not 'exactly alike'.", "misconceptionId": "overgeneralized_rule"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$The postulate of Dalton's atomic theory which still holds is that$q$, $q$[{"label": "A", "text": "all elements are made of small indivisible particles", "isCorrect": false}, {"label": "B", "text": "particles of different elements combine in a simple whole number ratio", "isCorrect": false}, {"label": "C", "text": "atoms can neither be created nor destroyed", "isCorrect": true}, {"label": "D", "text": "the particles of the same element are exactly alike", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$Modern chemistry has disproved several of Dalton's original postulates: atoms ARE divisible (into protons, neutrons, electrons), and atoms of the same element are NOT all exactly alike (isotopes exist). What still holds, and remains a cornerstone of chemistry, is that atoms are neither created nor destroyed in ordinary chemical reactions — the basis of the law of conservation of mass.$q$, $q$live$q$, $q$A: This postulate has since been disproved — atoms are made of subatomic particles (protons, neutrons, electrons) and are therefore divisible, contrary to Dalton's original claim. B: This describes combination in fixed ratios, which is still broadly true, but it is not the postulate most directly and universally cited as 'still holding' in the way atom conservation is — this is a plausible-sounding but not the intended best answer. D: This postulate has been disproved by the discovery of isotopes — atoms of the same element can have different masses (different numbers of neutrons), so they are not 'exactly alike'.$q$),
($q$chemistry_0359$q$, $q$Chemistry$q$, $q$Kinetic Theory & Gas Laws$q$, $q$Partial Pressure and Mole Fraction$q$, $q$Answer a real JAMB 2002 question on Partial Pressure and Mole Fraction.$q$, $q$[{"conceptId": "eo9w1a", "weight": 1}]$q$::jsonb, 3, $q$application$q$, 69, $q$medium$q$, $q$light$q$, $q$[{"option": "A", "explanation": "0.22 atm is too low for oxygen's actual mole fraction (~0.47) of the total pressure \u2014 this looks like the mole fraction was computed using the wrong denominator or the wrong gas's moles.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "0.44 atm overshoots \u2014 a common error here is treating oxygen's mole fraction as being close to cyclopropane's larger share instead of correctly dividing its own moles by the total.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "0.55 atm would correspond to oxygen being the majority component, but oxygen (0.66 mol) is actually the smaller quantity compared to cyclopropane (0.75 mol) \u2014 this option has the proportions backwards.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$If 0.75 mole of cyclopropane and 0.66 mole of oxygen are mixed in a vessel with a total pressure of 0.7 atmosphere, what is the partial pressure of oxygen in the mixture?$q$, $q$[{"label": "A", "text": "0.22 atmosphere", "isCorrect": false}, {"label": "B", "text": "0.33 atmosphere", "isCorrect": true}, {"label": "C", "text": "0.44 atmosphere", "isCorrect": false}, {"label": "D", "text": "0.55 atmosphere", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Partial pressure = mole fraction × total pressure. Total moles = 0.75 + 0.66 = 1.41. Mole fraction of O2 = 0.66/1.41 ≈ 0.468. Partial pressure of O2 = 0.468 × 0.7 ≈ 0.33 atm.$q$, $q$live$q$, $q$A: 0.22 atm is too low for oxygen's actual mole fraction (~0.47) of the total pressure — this looks like the mole fraction was computed using the wrong denominator or the wrong gas's moles. C: 0.44 atm overshoots — a common error here is treating oxygen's mole fraction as being close to cyclopropane's larger share instead of correctly dividing its own moles by the total. D: 0.55 atm would correspond to oxygen being the majority component, but oxygen (0.66 mol) is actually the smaller quantity compared to cyclopropane (0.75 mol) — this option has the proportions backwards.$q$),
($q$chemistry_0360$q$, $q$Chemistry$q$, $q$Metals & Their Compounds$q$, $q$Iron Compounds and Redox Behaviour$q$, $q$Answer a real JAMB 2002 question on Iron Compounds and Redox Behaviour.$q$, $q$[{"conceptId": "gc697d", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 57, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "Brown describes the original FeCl3 solution's colour before reaction, not the result of reduction \u2014 this picks the starting colour rather than the colour after H2S has acted on it.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "The solution doesn't become colourless \u2014 Fe2+ ions still impart a pale green colour in solution, they aren't colourless like some other ions might be.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "Pale red isn't a colour associated with either Fe3+ or Fe2+ in this kind of reaction \u2014 it doesn't match any real species formed here.", "misconceptionId": "guessed_no_reasoning"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$When H2S is passed into a solution of iron(III) chloride, the solution turns$q$, $q$[{"label": "A", "text": "brown", "isCorrect": false}, {"label": "B", "text": "pale green", "isCorrect": true}, {"label": "C", "text": "colourless", "isCorrect": false}, {"label": "D", "text": "pale red", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$H2S is a reducing agent and reduces yellow/brown Fe3+ to pale green Fe2+, while itself being oxidised to a pale precipitate of sulphur (giving the solution a cloudy pale-green/yellow appearance overall, but the characteristic colour change described is toward pale green from the Fe2+ formed).$q$, $q$live$q$, $q$A: Brown describes the original FeCl3 solution's colour before reaction, not the result of reduction — this picks the starting colour rather than the colour after H2S has acted on it. C: The solution doesn't become colourless — Fe2+ ions still impart a pale green colour in solution, they aren't colourless like some other ions might be. D: Pale red isn't a colour associated with either Fe3+ or Fe2+ in this kind of reaction — it doesn't match any real species formed here.$q$),
($q$chemistry_0361$q$, $q$Chemistry$q$, $q$Chemical Equilibrium$q$, $q$Thermodynamics of Equilibrium$q$, $q$Answer a real JAMB 2002 question on Thermodynamics of Equilibrium.$q$, $q$[{"conceptId": "pns65n", "weight": 1}]$q$::jsonb, 3, $q$application$q$, 69, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "This is just the general formula defining Gibbs free energy change \u2014 it doesn't by itself say anything about whether the system is specifically at equilibrium.", "misconceptionId": "misunderstood_terminology"}, {"option": "B", "explanation": "\u0394G < 0 means the forward reaction is still spontaneously proceeding \u2014 the system hasn't yet reached the point of no net change, so it isn't at equilibrium.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "\u0394G > 0 means the forward reaction is non-spontaneous (the reverse would be favoured) \u2014 this describes a system driven away from, not settled into, equilibrium.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$Which of the following equations shows that a reaction is in equilibrium?$q$, $q$[{"label": "A", "text": "\u0394G = \u0394H \u2212 T\u0394S", "isCorrect": false}, {"label": "B", "text": "\u0394G < 0", "isCorrect": false}, {"label": "C", "text": "\u0394G = 0", "isCorrect": true}, {"label": "D", "text": "\u0394G > 0", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$A system is at equilibrium exactly when its Gibbs free energy change is zero (ΔG = 0) — there's no further net driving force pushing the reaction forward or backward. ΔG < 0 indicates a spontaneous forward reaction still occurring, ΔG > 0 indicates non-spontaneity in the forward direction, and the first equation is simply the general defining relationship for ΔG, not a statement of equilibrium itself.$q$, $q$live$q$, $q$A: This is just the general formula defining Gibbs free energy change — it doesn't by itself say anything about whether the system is specifically at equilibrium. B: ΔG < 0 means the forward reaction is still spontaneously proceeding — the system hasn't yet reached the point of no net change, so it isn't at equilibrium. D: ΔG > 0 means the forward reaction is non-spontaneous (the reverse would be favoured) — this describes a system driven away from, not settled into, equilibrium.$q$),
($q$chemistry_0362$q$, $q$Chemistry$q$, $q$Oxidation & Reduction$q$, $q$Oxidation Number Assignment$q$, $q$Answer a real JAMB 2002 question on Oxidation Number Assignment.$q$, $q$[{"conceptId": "y963w7", "weight": 1}]$q$::jsonb, 3, $q$application$q$, 69, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "This has both the direction and the starting value wrong \u2014 copper doesn't start at 0 in Cu2S (it's a compound, not free metal), and it doesn't end at +2 since it ends as elemental Cu(s).", "misconceptionId": "sign_error"}, {"option": "B", "explanation": "This gets the direction backwards \u2014 copper is being reduced (going down in oxidation number, ending at elemental Cu = 0), not oxidised up from 0.", "misconceptionId": "sign_error"}, {"option": "D", "explanation": "This assumes the wrong starting oxidation state for copper in Cu2S \u2014 properly assigning sulfur as -2 forces each copper to be +1, not +2, in the reactant.", "misconceptionId": "formula_recall_error"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$Cu2S(s) + O2(g) → 2Cu(s) + SO2(g). What is the change in the oxidation number of copper in the reaction above?$q$, $q$[{"label": "A", "text": "0 to +2", "isCorrect": false}, {"label": "B", "text": "0 to +1", "isCorrect": false}, {"label": "C", "text": "+1 to 0", "isCorrect": true}, {"label": "D", "text": "+2 to +1", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$In Cu2S, sulfur (more electronegative) is assigned -2, so the two copper atoms together must total +2, giving each Cu an oxidation state of +1. In the product, copper appears as the free element Cu(s), which by definition has an oxidation state of 0. So copper's oxidation number changes from +1 to 0 — a reduction.$q$, $q$live$q$, $q$A: This has both the direction and the starting value wrong — copper doesn't start at 0 in Cu2S (it's a compound, not free metal), and it doesn't end at +2 since it ends as elemental Cu(s). B: This gets the direction backwards — copper is being reduced (going down in oxidation number, ending at elemental Cu = 0), not oxidised up from 0. D: This assumes the wrong starting oxidation state for copper in Cu2S — properly assigning sulfur as -2 forces each copper to be +1, not +2, in the reactant.$q$),
($q$chemistry_0363$q$, $q$Chemistry$q$, $q$Chemical Equilibrium$q$, $q$Le Chatelier's Principle — Pressure & Temperature Effects$q$, $q$Answer a real JAMB 2002 question on Le Chatelier's Principle — Pressure & Temperature Effects.$q$, $q$[{"conceptId": "kzcd9t", "weight": 1}]$q$::jsonb, 3, $q$application$q$, 69, $q$low$q$, $q$light$q$, $q$[{"option": "B", "explanation": "Reducing G, a product, would shift the equilibrium forward (to replace the removed product), not backward \u2014 this has the shift direction reversed relative to which species is removed.", "misconceptionId": "sign_error"}, {"option": "C", "explanation": "Increasing F, a reactant, would drive the equilibrium forward (more reactant available to react), favouring the forward, not the backward, reaction.", "misconceptionId": "sign_error"}, {"option": "D", "explanation": "Increasing E, a reactant, also pushes the equilibrium forward by Le Chatelier's principle, favouring more product formation \u2014 the opposite of favouring the backward reaction.", "misconceptionId": "sign_error"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$In the reaction E + F ⇌ G + H, the backward reaction is favoured if the concentration of$q$, $q$[{"label": "A", "text": "E is reduced", "isCorrect": true}, {"label": "B", "text": "G is reduced", "isCorrect": false}, {"label": "C", "text": "F is increased", "isCorrect": false}, {"label": "D", "text": "E is increased", "isCorrect": false}]$q$::jsonb, $q$A$q$, $q$The backward reaction (G + H → E + F) is favoured when the system shifts to replace something that's been removed from the reactant side. If E's concentration is reduced, Le Chatelier's principle predicts the equilibrium shifts to produce more E — meaning the backward reaction is favoured to replenish it.$q$, $q$live$q$, $q$B: Reducing G, a product, would shift the equilibrium forward (to replace the removed product), not backward — this has the shift direction reversed relative to which species is removed. C: Increasing F, a reactant, would drive the equilibrium forward (more reactant available to react), favouring the forward, not the backward, reaction. D: Increasing E, a reactant, also pushes the equilibrium forward by Le Chatelier's principle, favouring more product formation — the opposite of favouring the backward reaction.$q$),
($q$chemistry_0364$q$, $q$Chemistry$q$, $q$Electrolysis$q$, $q$Electrolysis of Aqueous Solutions — Preferential Discharge$q$, $q$Answer a real JAMB 2002 question on Electrolysis of Aqueous Solutions — Preferential Discharge.$q$, $q$[{"conceptId": "tqaefy", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 57, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "Na+ is far too reactive to be discharged at the cathode in aqueous solution \u2014 hydrogen from water is preferentially reduced there instead, so sodium metal is never actually produced.", "misconceptionId": "missing_prerequisite"}, {"option": "C", "explanation": "Water is the medium being electrolysed, not a 'product' in the usual sense here, and sodium (not present as a gas) is definitely not deposited \u2014 this option mismatches what's actually generated at the electrodes.", "misconceptionId": "misunderstood_terminology"}, {"option": "D", "explanation": "This combines two things that aren't the true electrode products \u2014 water isn't 'produced' (it's consumed), and sodium metal cannot be deposited from aqueous solution under these conditions.", "misconceptionId": "missing_prerequisite"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$The products of the electrolysis of dilute sodium hydroxide using platinum electrodes are$q$, $q$[{"label": "A", "text": "sodium metal and oxygen gas", "isCorrect": false}, {"label": "B", "text": "hydrogen and oxygen gases", "isCorrect": true}, {"label": "C", "text": "water and hydrogen gas", "isCorrect": false}, {"label": "D", "text": "water and sodium metal", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$In dilute aqueous NaOH, water is preferentially discharged at both electrodes rather than Na+ (too reactive to be discharged in aqueous solution) or OH- directly as a separate product — hydrogen gas forms at the cathode and oxygen gas forms at the anode, essentially electrolysing the water while the NaOH concentration in solution slowly increases.$q$, $q$live$q$, $q$A: Na+ is far too reactive to be discharged at the cathode in aqueous solution — hydrogen from water is preferentially reduced there instead, so sodium metal is never actually produced. C: Water is the medium being electrolysed, not a 'product' in the usual sense here, and sodium (not present as a gas) is definitely not deposited — this option mismatches what's actually generated at the electrodes. D: This combines two things that aren't the true electrode products — water isn't 'produced' (it's consumed), and sodium metal cannot be deposited from aqueous solution under these conditions.$q$),
($q$chemistry_0365$q$, $q$Chemistry$q$, $q$Chemical Equilibrium$q$, $q$Le Chatelier's Principle — Pressure & Temperature Effects$q$, $q$Answer a real JAMB 2002 question on Le Chatelier's Principle — Pressure & Temperature Effects.$q$, $q$[{"conceptId": "kzcd9t", "weight": 1}]$q$::jsonb, 3, $q$application$q$, 69, $q$low$q$, $q$light$q$, $q$[{"option": "B", "explanation": "Decreasing pressure favours the side with MORE gas moles (the products, 2 mol), not the side with fewer moles (PCl5, 1 mol) \u2014 this option has the shift direction backwards.", "misconceptionId": "sign_error"}, {"option": "C", "explanation": "Pressure changes shift the position of equilibrium, but they don't inherently 'accelerate' the reaction in the sense of increasing rate constant \u2014 this conflates equilibrium position with reaction rate/kinetics.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "Like the previous option, this confuses a shift in equilibrium position (which does happen) with a change in reaction speed (which pressure changes don't directly control here) \u2014 the correct effect is on yield, not tempo.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$PCl5(g) ⇌ PCl3(g) + Cl2(g). In the reaction above, a decrease in pressure will$q$, $q$[{"label": "A", "text": "increase the yield of PCl3", "isCorrect": true}, {"label": "B", "text": "increase the yield of PCl5", "isCorrect": false}, {"label": "C", "text": "accelerate the reaction", "isCorrect": false}, {"label": "D", "text": "decelerate the reaction", "isCorrect": false}]$q$::jsonb, $q$A$q$, $q$The forward reaction produces 2 moles of gas from 1 mole, increasing the total number of gas particles. By Le Chatelier's principle, decreasing pressure favours the side with more gas moles — so the equilibrium shifts forward, increasing PCl3 (and Cl2) yield.$q$, $q$live$q$, $q$B: Decreasing pressure favours the side with MORE gas moles (the products, 2 mol), not the side with fewer moles (PCl5, 1 mol) — this option has the shift direction backwards. C: Pressure changes shift the position of equilibrium, but they don't inherently 'accelerate' the reaction in the sense of increasing rate constant — this conflates equilibrium position with reaction rate/kinetics. D: Like the previous option, this confuses a shift in equilibrium position (which does happen) with a change in reaction speed (which pressure changes don't directly control here) — the correct effect is on yield, not tempo.$q$),
($q$chemistry_0366$q$, $q$Chemistry$q$, $q$Rates of Reaction$q$, $q$Activation Energy and Catalysts$q$, $q$Answer a real JAMB 2002 question on Activation Energy and Catalysts.$q$, $q$[{"conceptId": "c4kxyo", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 25, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "A catalyst affects the rate by lowering activation energy, but the Arrhenius equation itself doesn't have a 'catalyst' term \u2014 it expresses rate in terms of activation energy and temperature directly.", "misconceptionId": "misunderstood_terminology"}, {"option": "C", "explanation": "Molecular collisions are the qualitative basis of collision theory, but the Arrhenius equation is the specific mathematical/quantitative relationship involving activation energy, not a general statement about collisions.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "Heat of reaction (\u0394H) describes energy released/absorbed overall by the reaction, which is a different quantity from activation energy (the energy barrier to be overcome) \u2014 the Arrhenius equation is about the latter.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$The Arrhenius equation expresses the relationship between the speed of a reaction and its$q$, $q$[{"label": "A", "text": "catalyst", "isCorrect": false}, {"label": "B", "text": "activation energy", "isCorrect": true}, {"label": "C", "text": "molecular collisions", "isCorrect": false}, {"label": "D", "text": "heat of reaction", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$The Arrhenius equation (k = A·e^(-Ea/RT)) mathematically relates the rate constant k to temperature and the activation energy Ea — it's specifically the quantitative link between reaction rate and activation energy (and temperature).$q$, $q$live$q$, $q$A: A catalyst affects the rate by lowering activation energy, but the Arrhenius equation itself doesn't have a 'catalyst' term — it expresses rate in terms of activation energy and temperature directly. C: Molecular collisions are the qualitative basis of collision theory, but the Arrhenius equation is the specific mathematical/quantitative relationship involving activation energy, not a general statement about collisions. D: Heat of reaction (ΔH) describes energy released/absorbed overall by the reaction, which is a different quantity from activation energy (the energy barrier to be overcome) — the Arrhenius equation is about the latter.$q$),
($q$chemistry_0367$q$, $q$Chemistry$q$, $q$Electrolysis$q$, $q$Faraday's Laws$q$, $q$Answer a real JAMB 2002 question on Faraday's Laws.$q$, $q$[{"conceptId": "cbvosp", "weight": 1}]$q$::jsonb, 3, $q$application$q$, 69, $q$medium$q$, $q$light$q$, $q$[{"option": "A", "explanation": "8.04 g is 4\u00d7 too large \u2014 this likely comes from not properly tracking the shared quantity of electricity (moles of electrons) between the two half-reactions, both of which involve 2 electrons per ion.", "misconceptionId": "arithmetic_slip"}, {"option": "B", "explanation": "4.02 g is double the correct value \u2014 a likely mismatch between the moles of electrons calculated from zinc and the moles of Hg actually deposited by that same charge.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "1.00 g doesn't correspond to any straightforward variant of this calculation \u2014 likely from a mis-stepped mole-to-mass conversion at the final stage.", "misconceptionId": "unit_conversion_error"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$What amount of mercury would be liberated if the same quantity of electricity that liberated 0.65 g of zinc is supplied? [Zn = 65, Hg = 201]$q$, $q$[{"label": "A", "text": "8.04 g", "isCorrect": false}, {"label": "B", "text": "4.02 g", "isCorrect": false}, {"label": "C", "text": "2.01 g", "isCorrect": true}, {"label": "D", "text": "1.00 g", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$Moles of Zn = 0.65/65 = 0.01 mol. Since Zn2+ needs 2 electrons per ion, total charge passed = 0.01 × 2 = 0.02 mol of electrons. For Hg2+ (also needing 2 electrons per ion), moles of Hg deposited = 0.02/2 = 0.01 mol. Mass of Hg = 0.01 × 201 = 2.01 g.$q$, $q$live$q$, $q$A: 8.04 g is 4× too large — this likely comes from not properly tracking the shared quantity of electricity (moles of electrons) between the two half-reactions, both of which involve 2 electrons per ion. B: 4.02 g is double the correct value — a likely mismatch between the moles of electrons calculated from zinc and the moles of Hg actually deposited by that same charge. D: 1.00 g doesn't correspond to any straightforward variant of this calculation — likely from a mis-stepped mole-to-mass conversion at the final stage.$q$),
($q$chemistry_0368$q$, $q$Chemistry$q$, $q$Energy Changes$q$, $q$Enthalpy of Dissolution$q$, $q$Answer a real JAMB 2002 question on Enthalpy of Dissolution.$q$, $q$[{"conceptId": "fiv6k4", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 25, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Speed of dissolving ('rapid') describes kinetics, not the energy change (heat released or absorbed) \u2014 the question is asking about the thermal nature of the process, which this option doesn't address.", "misconceptionId": "misunderstood_terminology"}, {"option": "B", "explanation": "Like option A, this describes the rate of dissolving, not whether heat is released or absorbed \u2014 it answers a different question than the one being asked.", "misconceptionId": "misunderstood_terminology"}, {"option": "D", "explanation": "This has the energy direction backwards \u2014 NaOH dissolving releases heat (exothermic), it doesn't absorb it (endothermic) as this option claims.", "misconceptionId": "sign_error"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$When dissolved in water, NaOH flakes show$q$, $q$[{"label": "A", "text": "a rapid reaction", "isCorrect": false}, {"label": "B", "text": "a slow reaction", "isCorrect": false}, {"label": "C", "text": "an exothermic change", "isCorrect": true}, {"label": "D", "text": "an endothermic change", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$Dissolving NaOH in water is a strongly exothermic process — the container noticeably heats up as the solid dissolves, a well-known and commonly demonstrated property of sodium hydroxide.$q$, $q$live$q$, $q$A: Speed of dissolving ('rapid') describes kinetics, not the energy change (heat released or absorbed) — the question is asking about the thermal nature of the process, which this option doesn't address. B: Like option A, this describes the rate of dissolving, not whether heat is released or absorbed — it answers a different question than the one being asked. D: This has the energy direction backwards — NaOH dissolving releases heat (exothermic), it doesn't absorb it (endothermic) as this option claims.$q$),
($q$chemistry_0369$q$, $q$Chemistry$q$, $q$Non-Metals & Their Compounds$q$, $q$Qualitative Tests for Water$q$, $q$Answer a real JAMB 2002 question on Qualitative Tests for Water.$q$, $q$[{"conceptId": "ozo4oh", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 25, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "This has the starting colour right but the ending colour wrong \u2014 hydrated cobalt chloride turns pink, not white; white is actually closer to anhydrous copper(II) sulphate's behaviour in a similar water-detection test, a common mix-up between the two classic tests.", "misconceptionId": "confused_similar_concepts"}, {"option": "B", "explanation": "Neither colour matches \u2014 anhydrous cobalt chloride is blue (not white), and it turns pink (not green) on hydration.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "Anhydrous cobalt chloride isn't white to begin with (it's blue), and it turns pink rather than red on hydration \u2014 both ends of this option are incorrect.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$Steam changes the colour of anhydrous cobalt(II) chloride from$q$, $q$[{"label": "A", "text": "blue to white", "isCorrect": false}, {"label": "B", "text": "white to green", "isCorrect": false}, {"label": "C", "text": "blue to pink", "isCorrect": true}, {"label": "D", "text": "white to red", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$Anhydrous cobalt(II) chloride is blue; when it absorbs water (as from steam), it turns pink as it becomes hydrated (CoCl2·6H2O) — this colour change is the standard test used to detect the presence of water.$q$, $q$live$q$, $q$A: This has the starting colour right but the ending colour wrong — hydrated cobalt chloride turns pink, not white; white is actually closer to anhydrous copper(II) sulphate's behaviour in a similar water-detection test, a common mix-up between the two classic tests. B: Neither colour matches — anhydrous cobalt chloride is blue (not white), and it turns pink (not green) on hydration. D: Anhydrous cobalt chloride isn't white to begin with (it's blue), and it turns pink rather than red on hydration — both ends of this option are incorrect.$q$),
($q$chemistry_0370$q$, $q$Chemistry$q$, $q$Acids, Bases & Salts$q$, $q$pH and Reactivity Toward Metals$q$, $q$Answer a real JAMB 2002 question on pH and Reactivity Toward Metals.$q$, $q$[{"conceptId": "qs067o", "weight": 1}]$q$::jsonb, 3, $q$application$q$, 69, $q$medium$q$, $q$light$q$, $q$[{"option": "B", "explanation": "1.0\u00d710\u207b\u2076 mol/dm3 OH\u207b corresponds to pH 8 \u2014 mildly alkaline, not acidic enough to react with magnesium metal and release hydrogen gas.", "misconceptionId": "sign_error"}, {"option": "C", "explanation": "1.0\u00d710\u207b\u2074 mol/dm3 OH\u207b corresponds to pH 10, a clearly alkaline solution \u2014 magnesium won't react with an alkaline solution to release H2 this way.", "misconceptionId": "sign_error"}, {"option": "D", "explanation": "1.0\u00d710\u207b\u00b2 mol/dm3 OH\u207b is the HIGHEST hydroxide concentration listed, corresponding to a strongly alkaline solution (pH 12) \u2014 picking the largest [OH-] value here mistakes 'more OH-' for 'more reactive', when it's actually the opposite (least acidic) of these options.", "misconceptionId": "sign_error"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$Which of the following solutions containing only hydroxyl ions will liberate hydrogen gas when reacted with magnesium metal?$q$, $q$[{"label": "A", "text": "1.0 \u00d7 10\u207b\u00b9\u00b2 mol dm\u207b\u00b3", "isCorrect": true}, {"label": "B", "text": "1.0 \u00d7 10\u207b\u2076 mol dm\u207b\u00b3", "isCorrect": false}, {"label": "C", "text": "1.0 \u00d7 10\u207b\u2074 mol dm\u207b\u00b3", "isCorrect": false}, {"label": "D", "text": "1.0 \u00d7 10\u207b\u00b2 mol dm\u207b\u00b3", "isCorrect": false}]$q$::jsonb, $q$A$q$, $q$A LOWER hydroxide ion concentration means a MORE acidic solution (since [H+][OH-] = 10^-14 at 25°C, a small [OH-] implies a large [H+]). Of the given concentrations, 1.0×10⁻¹² mol/dm3 OH⁻ corresponds to the lowest [OH-] and therefore the highest [H+] (pH ≈ 2) — acidic enough to react with magnesium and liberate hydrogen gas. The other options have progressively higher [OH-], meaning less acidic (even alkaline) conditions that won't react with Mg to release H2.$q$, $q$live$q$, $q$B: 1.0×10⁻⁶ mol/dm3 OH⁻ corresponds to pH 8 — mildly alkaline, not acidic enough to react with magnesium metal and release hydrogen gas. C: 1.0×10⁻⁴ mol/dm3 OH⁻ corresponds to pH 10, a clearly alkaline solution — magnesium won't react with an alkaline solution to release H2 this way. D: 1.0×10⁻² mol/dm3 OH⁻ is the HIGHEST hydroxide concentration listed, corresponding to a strongly alkaline solution (pH 12) — picking the largest [OH-] value here mistakes 'more OH-' for 'more reactive', when it's actually the opposite (least acidic) of these options.$q$),
($q$chemistry_0371$q$, $q$Chemistry$q$, $q$Solubility$q$, $q$Solubility and Saturation$q$, $q$Answer a real JAMB 2002 question on Solubility and Saturation.$q$, $q$[{"conceptId": "mu3oy8", "weight": 1}]$q$::jsonb, 3, $q$application$q$, 84, $q$medium$q$, $q$moderate$q$, $q$[{"option": "A", "explanation": "Saturated would mean the solution holds exactly the maximum dissolvable amount (0.34 mol/dm3) \u2014 but the actual concentration here (\u22480.135 mol/dm3) is well below that limit, so it isn't saturated yet.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "Supersaturated means holding MORE than the normal solubility limit, an unstable state \u2014 the calculated concentration here is well below, not above, the solubility limit, so this is the opposite of what's happening.", "misconceptionId": "overgeneralized_rule"}, {"option": "D", "explanation": "'Complete dissolution' is explicitly stated in the question \u2014 a suspension implies undissolved solid particles remaining, which contradicts the given information.", "misconceptionId": "misunderstood_terminology"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$The solubility of a salt of molar mass 101 g at 20°C is 0.34 mol dm⁻³. If 3.40 g of the salt is dissolved completely in 250 cm3 of water in a beaker, the resulting solution is$q$, $q$[{"label": "A", "text": "saturated", "isCorrect": false}, {"label": "B", "text": "unsaturated", "isCorrect": true}, {"label": "C", "text": "supersaturated", "isCorrect": false}, {"label": "D", "text": "a suspension", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Moles dissolved = 3.40/101 ≈ 0.0337 mol. Concentration = 0.0337 mol / 0.250 dm3 ≈ 0.135 mol dm⁻³. Since this (0.135) is well below the solubility limit (0.34 mol dm⁻³), more salt could still dissolve — the solution is unsaturated.$q$, $q$live$q$, $q$A: Saturated would mean the solution holds exactly the maximum dissolvable amount (0.34 mol/dm3) — but the actual concentration here (≈0.135 mol/dm3) is well below that limit, so it isn't saturated yet. C: Supersaturated means holding MORE than the normal solubility limit, an unstable state — the calculated concentration here is well below, not above, the solubility limit, so this is the opposite of what's happening. D: 'Complete dissolution' is explicitly stated in the question — a suspension implies undissolved solid particles remaining, which contradicts the given information.$q$),
($q$chemistry_0372$q$, $q$Chemistry$q$, $q$Acids, Bases & Salts$q$, $q$Titration Calculations$q$, $q$Answer a real JAMB 2002 question on Titration Calculations.$q$, $q$[{"conceptId": "e6pk77", "weight": 1}]$q$::jsonb, 3, $q$application$q$, 84, $q$medium$q$, $q$moderate$q$, $q$[{"option": "A", "explanation": "0.2 mol/dm3 assumes a 1:1 mole ratio between Na2CO3 and HCl, ignoring that the balanced equation requires 2 moles of HCl for every mole of Na2CO3.", "misconceptionId": "missing_prerequisite"}, {"option": "B", "explanation": "0.4 mol/dm3 is close but slightly under the correct value \u2014 likely from a small arithmetic slip in the final division step rather than a conceptual error in the mole ratio.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "0.6 mol/dm3 overshoots the correct value \u2014 possibly from using a wrong volume or overestimating the required moles of HCl at some step.", "misconceptionId": "arithmetic_slip"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$25 cm3 of a 0.2 mol dm⁻³ solution of Na2CO3 requires 20 cm3 of a solution of HCl for neutralization. The concentration of the HCl solution is$q$, $q$[{"label": "A", "text": "0.2 mol dm\u207b\u00b3", "isCorrect": false}, {"label": "B", "text": "0.4 mol dm\u207b\u00b3", "isCorrect": false}, {"label": "C", "text": "0.5 mol dm\u207b\u00b3", "isCorrect": true}, {"label": "D", "text": "0.6 mol dm\u207b\u00b3", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$Na2CO3 + 2HCl → 2NaCl + H2O + CO2, so 1 mole of Na2CO3 needs 2 moles of HCl. Moles Na2CO3 = 0.025 dm3 × 0.2 mol/dm3 = 0.005 mol, requiring 0.01 mol HCl. Concentration of HCl = 0.01 mol / 0.020 dm3 = 0.5 mol dm⁻³.$q$, $q$live$q$, $q$A: 0.2 mol/dm3 assumes a 1:1 mole ratio between Na2CO3 and HCl, ignoring that the balanced equation requires 2 moles of HCl for every mole of Na2CO3. B: 0.4 mol/dm3 is close but slightly under the correct value — likely from a small arithmetic slip in the final division step rather than a conceptual error in the mole ratio. D: 0.6 mol/dm3 overshoots the correct value — possibly from using a wrong volume or overestimating the required moles of HCl at some step.$q$),
($q$chemistry_0373$q$, $q$Chemistry$q$, $q$Chemical Combination$q$, $q$Hydrates and Water of Crystallization$q$, $q$Answer a real JAMB 2002 question on Hydrates and Water of Crystallization.$q$, $q$[{"conceptId": "sdx4xa", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 25, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Effervescence refers to a substance fizzing/bubbling as gas escapes \u2014 an entirely different phenomenon involving gas release, not water loss from a crystal structure.", "misconceptionId": "misunderstood_terminology"}, {"option": "C", "explanation": "Fluorescence is an optical phenomenon (emitting light after absorbing radiation) \u2014 completely unrelated to water loss from hydrated crystals; the similar-sounding name is likely the source of confusion.", "misconceptionId": "misunderstood_terminology"}, {"option": "D", "explanation": "Deliquescence is the opposite process \u2014 a substance absorbing moisture from the air until it dissolves in it \u2014 not losing water as described in the question.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$When a salt loses its water of crystallization to the atmosphere on exposure, the process is said to be$q$, $q$[{"label": "A", "text": "effervescence", "isCorrect": false}, {"label": "B", "text": "efflorescence", "isCorrect": true}, {"label": "C", "text": "fluorescence", "isCorrect": false}, {"label": "D", "text": "deliquescence", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Efflorescence is specifically the loss of water of crystallization from a hydrated salt to the surrounding air, often leaving a powdery residue. Effervescence refers to bubbling/gas release, fluorescence is a light-emission phenomenon, and deliquescence is the opposite process — a substance absorbing so much moisture from the air that it dissolves itself.$q$, $q$live$q$, $q$A: Effervescence refers to a substance fizzing/bubbling as gas escapes — an entirely different phenomenon involving gas release, not water loss from a crystal structure. C: Fluorescence is an optical phenomenon (emitting light after absorbing radiation) — completely unrelated to water loss from hydrated crystals; the similar-sounding name is likely the source of confusion. D: Deliquescence is the opposite process — a substance absorbing moisture from the air until it dissolves in it — not losing water as described in the question.$q$),
($q$chemistry_0374$q$, $q$Chemistry$q$, $q$Acids, Bases & Salts$q$, $q$pH Scale$q$, $q$Answer a real JAMB 2002 question on pH Scale.$q$, $q$[{"conceptId": "ab1gw8", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 72, $q$medium$q$, $q$moderate$q$, $q$[{"option": "A", "explanation": "Adding a base should raise pH, not lower it \u2014 this option has the direction of the pH shift backwards for the reagent being added.", "misconceptionId": "sign_error"}, {"option": "C", "explanation": "Even a small addition of a concentrated strong base changes the ion balance in the solution \u2014 the pH won't stay perfectly unaltered, however slight the shift.", "misconceptionId": "overgeneralized_rule"}, {"option": "D", "explanation": "Pure water has pH 7, which is actually LOWER than the starting 8.4 \u2014 since a base is being added (raising pH further above 8.4), the result moves away from, not toward, neutral pure water.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$Three drops of 1.0 mol dm⁻³ solution of NaOH are added to 20 cm3 of a solution of pH 8.4. The pH of the resulting solution will be$q$, $q$[{"label": "A", "text": "less than 8.4", "isCorrect": false}, {"label": "B", "text": "greater than 8.4", "isCorrect": true}, {"label": "C", "text": "unaltered", "isCorrect": false}, {"label": "D", "text": "close to that of pure water", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Adding a strong base (NaOH) to any solution increases its hydroxide ion concentration, pushing the pH upward — so even a small addition raises the pH above the original 8.4.$q$, $q$live$q$, $q$A: Adding a base should raise pH, not lower it — this option has the direction of the pH shift backwards for the reagent being added. C: Even a small addition of a concentrated strong base changes the ion balance in the solution — the pH won't stay perfectly unaltered, however slight the shift. D: Pure water has pH 7, which is actually LOWER than the starting 8.4 — since a base is being added (raising pH further above 8.4), the result moves away from, not toward, neutral pure water.$q$),
($q$chemistry_0375$q$, $q$Chemistry$q$, $q$Non-Metals & Their Compounds$q$, $q$Sulphur Compounds$q$, $q$Answer a real JAMB 2002 question on Sulphur Compounds.$q$, $q$[{"conceptId": "2eamtt", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 57, $q$low$q$, $q$light$q$, $q$[{"option": "B", "explanation": "Hydrolysis means breaking a bond using water; sulphuric acid's skin-burning action does the opposite \u2014 it aggressively removes water from tissue rather than adding it in a bond-breaking reaction.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "Hydration means combining with or absorbing water in a more benign, often reversible sense \u2014 but concentrated sulphuric acid's action on skin is destructive and irreversible dehydration, not just simple hydration.", "misconceptionId": "misunderstood_terminology"}, {"option": "D", "explanation": "While the reaction is exothermic and does generate heat, the destructive mechanism itself (why the skin actually burns/chars) is chemical dehydration, not simply externally applied heating.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$Tetraoxosulphate(VI) acid burns the skin by$q$, $q$[{"label": "A", "text": "dehydration", "isCorrect": true}, {"label": "B", "text": "hydrolysis", "isCorrect": false}, {"label": "C", "text": "hydration", "isCorrect": false}, {"label": "D", "text": "heating", "isCorrect": false}]$q$::jsonb, $q$A$q$, $q$Concentrated sulphuric acid (tetraoxosulphate(VI) acid) has a powerful affinity for water and rips hydrogen and oxygen atoms out of organic tissue in the ratio found in water, charring it — this is dehydration, the same effect seen when it chars sugar or paper.$q$, $q$live$q$, $q$B: Hydrolysis means breaking a bond using water; sulphuric acid's skin-burning action does the opposite — it aggressively removes water from tissue rather than adding it in a bond-breaking reaction. C: Hydration means combining with or absorbing water in a more benign, often reversible sense — but concentrated sulphuric acid's action on skin is destructive and irreversible dehydration, not just simple hydration. D: While the reaction is exothermic and does generate heat, the destructive mechanism itself (why the skin actually burns/chars) is chemical dehydration, not simply externally applied heating.$q$),
($q$chemistry_0376$q$, $q$Chemistry$q$, $q$Environmental Pollution$q$, $q$Natural vs. Synthetic Pollutants$q$, $q$Answer a real JAMB 2002 question on Natural vs. Synthetic Pollutants.$q$, $q$[{"conceptId": "4w8vof", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 57, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "Uranium and its compounds are well-documented radioactive/toxic environmental hazards \u2014 a recognised pollutant, not the least-considered one.", "misconceptionId": "confused_similar_concepts"}, {"option": "B", "explanation": "Lead compounds are classic heavy-metal pollutants, notorious for toxicity in water, soil, and historically in fuel/paint \u2014 clearly a recognised pollution source.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "Organophosphorus compounds (common in pesticides) are widely recognised environmental and health hazards, not a substance overlooked as a pollution source.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$The substance least considered as a source of environmental pollution is$q$, $q$[{"label": "A", "text": "uranium", "isCorrect": false}, {"label": "B", "text": "lead compounds", "isCorrect": false}, {"label": "C", "text": "organophosphorous compounds", "isCorrect": false}, {"label": "D", "text": "silicate minerals", "isCorrect": true}]$q$::jsonb, $q$D$q$, $q$Uranium (radioactive contamination), lead compounds (heavy metal toxicity), and organophosphorus compounds (pesticide toxicity) are all well-known, actively-cited environmental and health hazards. Silicate minerals, by contrast, are common, largely chemically inert natural rock/soil components and are not typically classified as pollutants.$q$, $q$live$q$, $q$A: Uranium and its compounds are well-documented radioactive/toxic environmental hazards — a recognised pollutant, not the least-considered one. B: Lead compounds are classic heavy-metal pollutants, notorious for toxicity in water, soil, and historically in fuel/paint — clearly a recognised pollution source. C: Organophosphorus compounds (common in pesticides) are widely recognised environmental and health hazards, not a substance overlooked as a pollution source.$q$),
($q$chemistry_0377$q$, $q$Chemistry$q$, $q$Atomic Structure & Bonding$q$, $q$Hydrogen Bonding$q$, $q$Answer a real JAMB 2002 question on Hydrogen Bonding.$q$, $q$[{"conceptId": "jis2pp", "weight": 1}]$q$::jsonb, 1, $q$application$q$, 45, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "Alcohols are covalent molecular compounds, not ionic \u2014 they don't dissociate into ions, so 'ionic character' isn't the relevant property explaining their water solubility.", "misconceptionId": "misunderstood_terminology"}, {"option": "B", "explanation": "Boiling point is a physical property related to intermolecular forces overall, but it isn't itself the reason for water solubility \u2014 it's a consequence of hydrogen bonding, not the explanatory cause being asked about.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "Being covalent is true of alcohols generally, but covalency alone doesn't explain solubility in water \u2014 many covalent substances are actually insoluble in water; it's specifically the hydrogen-bonding capability of the -OH group that matters.", "misconceptionId": "overgeneralized_rule"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$The property which makes alcohol soluble in water is the$q$, $q$[{"label": "A", "text": "ionic character", "isCorrect": false}, {"label": "B", "text": "boiling point", "isCorrect": false}, {"label": "C", "text": "covalent nature", "isCorrect": false}, {"label": "D", "text": "hydrogen bonding", "isCorrect": true}]$q$::jsonb, $q$D$q$, $q$Alcohols dissolve readily in water because their -OH group can form hydrogen bonds with water molecules, just as water molecules hydrogen-bond with each other — this specific intermolecular attraction is what allows the two very different-looking substances to mix freely.$q$, $q$live$q$, $q$A: Alcohols are covalent molecular compounds, not ionic — they don't dissociate into ions, so 'ionic character' isn't the relevant property explaining their water solubility. B: Boiling point is a physical property related to intermolecular forces overall, but it isn't itself the reason for water solubility — it's a consequence of hydrogen bonding, not the explanatory cause being asked about. C: Being covalent is true of alcohols generally, but covalency alone doesn't explain solubility in water — many covalent substances are actually insoluble in water; it's specifically the hydrogen-bonding capability of the -OH group that matters.$q$),
($q$chemistry_0378$q$, $q$Chemistry$q$, $q$Air and Water$q$, $q$Water Treatment and Hardness$q$, $q$Answer a real JAMB 2002 question on Water Treatment and Hardness.$q$, $q$[{"conceptId": "beypy2", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 57, $q$low$q$, $q$light$q$, $q$[{"option": "B", "explanation": "Calcium trioxocarbonate(IV) (CaCO3) is what DEPOSITS as the fur after boiling \u2014 it's insoluble and isn't what's dissolved in the water beforehand; this confuses the cause (dissolved bicarbonate) with the result (insoluble carbonate scale).", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "Calcium tetraoxosulphate(VI) (CaSO4) causes a different type of hardness (permanent hardness), which isn't removed by boiling and isn't the salt responsible for kettle-furring specifically from boiling temporary hardness.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "Calcium hydroxide isn't the salt naturally dissolved in hard water from geological sources \u2014 it's not the species responsible for this furring process.", "misconceptionId": "misunderstood_terminology"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$The furring of kettles is caused by the presence in water of$q$, $q$[{"label": "A", "text": "calcium hydrogentrioxocarbonate(IV)", "isCorrect": true}, {"label": "B", "text": "calcium trioxocarbonate(IV)", "isCorrect": false}, {"label": "C", "text": "calcium tetraoxosulphate(VI)", "isCorrect": false}, {"label": "D", "text": "calcium hydroxide", "isCorrect": false}]$q$::jsonb, $q$A$q$, $q$Temporary hardness in water is caused by dissolved calcium hydrogencarbonate (Ca(HCO3)2), which is soluble. On boiling, it decomposes to insoluble calcium carbonate (CaCO3), releasing CO2 and water — that insoluble CaCO3 is the 'fur'/scale that deposits inside kettles. The question asks what's present IN the water beforehand, which is the soluble bicarbonate, not the insoluble carbonate that forms afterward.$q$, $q$live$q$, $q$B: Calcium trioxocarbonate(IV) (CaCO3) is what DEPOSITS as the fur after boiling — it's insoluble and isn't what's dissolved in the water beforehand; this confuses the cause (dissolved bicarbonate) with the result (insoluble carbonate scale). C: Calcium tetraoxosulphate(VI) (CaSO4) causes a different type of hardness (permanent hardness), which isn't removed by boiling and isn't the salt responsible for kettle-furring specifically from boiling temporary hardness. D: Calcium hydroxide isn't the salt naturally dissolved in hard water from geological sources — it's not the species responsible for this furring process.$q$);;
